    'financial_activation_gates_o2' => 'আসল চালুর আগে লিখিত অনুমোদন ও সবকিছু প্রস্তুত থাকার প্রমাণ থাকে।',
    'financial_activation_gates_o3' => 'সাপোর্ট স্টাফ টাকার হিসাব কেন বন্ধ তা বুঝিয়ে বলতে পারেন, নিজে থেকে চালুর তারিখ বানিয়ে বলেন না।',
    'financial_activation_gates_purpose' => 'মদিনা “সফটওয়্যার প্রস্তুত” আর “ব্যবসা আসলে চালু”—এই দুটো আলাদা রাখে। ট্রায়াল মোড ও লাইভ টাকার সুইচ আসল টাকা সুরক্ষিত রাখে।',
    'financial_activation_gates_s1' => 'দুটি সুইচ চিনে নিন: ট্রায়াল মোড ও লাইভ টাকার হিসাব (আর আলাদা অটো-রিলিজ সেটিং)।',
    'financial_activation_gates_s2' => 'লাইভ টাকার হিসাব বন্ধ থাকলেও ক্যালকুলেটর ও ডিলারদের অনেক পাতা চলে, কিন্তু আসল কোনো পাওনা বা আয় তৈরি হয় না।',
    'financial_activation_gates_s3' => 'চালুর সিদ্ধান্ত নেওয়ার আগে সিস্টেম প্রস্তুতির চেক চালান।',
    'financial_activation_gates_s4' => 'শুরুর ব্যালেন্স ও কমিশনের নিয়ম হিসাব বিভাগের আলাদা একজনকে দিয়ে যাচাই করান।',
    'financial_activation_gates_s5' => 'লাইভ টাকার হিসাব শুধু নিয়ন্ত্রিত চালুর সেটিং থেকেই চালু করুন, তাড়াহুড়ো করে সার্ভারে বদল করে নয়।',
    'financial_activation_gates_s6' => 'সঠিক তারিখ ও সময় দিয়ে সার্কুলারের মাধ্যমে ডিলারদের চালুর খবর দিন।',
    'financial_activation_gates_s7' => 'প্রথম দিন হিসাব খাতা ও পেমেন্টের দিকে বিশেষ নজর রাখুন।',
    'financial_activation_gates_s8' => 'লাইভ টাকার হিসাব থামাতে হলে কী করবেন, তার পরিকল্পনা আগেই রাখুন।',
    'financial_activation_gates_summary' => 'টাকার হিসাব কেন বন্ধ থাকতে পারে এবং চালুর আগে মালিককে কী যাচাই করতে হবে, বুঝুন।',
    'financial_activation_gates_t1' => 'শেয়ার করা ডেমো সিস্টেমে লাইভ টাকার হিসাব বন্ধ রাখুন।',
    'financial_activation_gates_t2' => 'সাপোর্ট স্টাফকে শেখান কীভাবে তারিখের কথা না দিয়ে সুইচের বিষয়টি বোঝাতে হয়।',
    'financial_activation_gates_t3' => 'লাইভ টাকার হিসাব চালু করার সময় ব্যাকআপ ঠিক আছে কিনা দেখুন।',
    'financial_activation_gates_title' => 'লাইভ টাকার হিসাব, ট্রায়াল মোড ও আসল চালু',
    'financial_activation_gates_w1' => 'তথ্য অসম্পূর্ণ থাকলে শুধু “খালি ওয়ালেট ঠিক করতে” লাইভ টাকার হিসাব চালু করবেন না।',
    'financial_activation_gates_w2' => 'আসল ব্যবসার সিস্টেমে কখনো ডেমো তথ্য চালাবেন না।',
    'financial_activation_gates_w3' => 'অটো-রিলিজ একটি আলাদা সুইচ। এটি নিজে থেকে চালু হয় না।',
    'financial_activation_gates_why' => 'শুরুর ব্যালেন্স অসম্পূর্ণ রেখে তাড়াতাড়ি টাকার হিসাব চালু করলে এমন ভুল আয় তৈরি হতে পারে যা আর ফেরানো যায় না।',
    'getting_started_badge' => 'শুরু করুন',
    'getting_started_o1' => 'আপনি সঠিক প্যানেলে লগইন করেছেন এবং আপনার পদের জন্য অনুমোদিত অংশগুলো দেখছেন।',
    'getting_started_o2' => 'লাইভ গাইড ট্যুর আর খোঁজা যায় এমন এই ব্যবহার নির্দেশিকার পার্থক্য আপনি জানেন।',
    'getting_started_o3' => 'যে পাতায় আছেন সেখান থেকেই যেকোনো সময় সাহায্য খুলতে পারেন।',
    'getting_started_purpose' => 'এই অধ্যায় মালিক, স্টাফ, ডিলার ও সাব-ডিলার—সবাইকে নিরাপদে সঠিক প্যানেলে লগইন করতে এবং প্রতিদিনের কাজের জন্য প্রস্তুত হতে সাহায্য করে।',
    'getting_started_s1' => 'আপনার লগইন পাতা চিনে নিন: মালিক — sadmin, স্টাফ — manage, ডিলার — dealer, সাব-ডিলার — subdealer। পাবলিক ওয়েবসাইট শুধু দেখার জন্য।',
    'getting_started_s10' => 'প্রথম লগইনের পর টাকা তোলা বা বড় অর্ডারের মতো কাজ করার আগে প্রোফাইল ও নিরাপত্তার তথ্য হালনাগাদ করুন।',
    'getting_started_s2' => 'আপনার প্যানেলের লগইন পাতা খুলে ইমেইল বা ফোন (ডিলার ও সাব-ডিলাররা ডিলার কোডও দিতে পারেন) ও পাসওয়ার্ড দিয়ে লগইন করুন।',
    'getting_started_s3' => 'OTP বা দুই ধাপের লগইন (2FA) চালু থাকলে ড্যাশবোর্ড খোলার আগে কোডটি দিন।',
    'getting_started_s4' => 'প্রথম লগইনে লাইভ গাইড ট্যুর এলে তা শেষ করুন। এটি শুধু ড্যাশবোর্ডের প্রধান বাটনগুলো দেখায়। এই লিখিত নির্দেশিকা আলাদা এবং এতে আরও বিস্তারিত আছে।',
    'getting_started_s5' => 'ওপরের বারে আপনার নাম, পদ, ভাষা বদলের বাটন ও দিন/রাত বাটন আছে কিনা দেখুন। শুরুতে দিনের (হালকা) মোড চালু থাকে।',
    'getting_started_s6' => 'ড্যাশবোর্ডের সংখ্যা দেখুন: অর্ডার, ডেলিভারি, আয় ও ওয়ালেট, এবং আগের ধাপ শেষ করতে বলা কোনো ব্যানার থাকলে সেটি।',
    'getting_started_s7' => 'অধ্যায় খুঁজতে, ড্যাশবোর্ড ট্যুর আবার চালাতে বা সাপোর্ট অনুরোধ পাঠাতে যেকোনো সময় অ্যাকাউন্ট মেনু বা সাইডবার থেকে সাহায্য (ব্যবহার নির্দেশিকা ও সাপোর্ট) খুলুন।',
    'getting_started_s8' => 'শুধু নিজের প্যানেলের ঠিকানা বুকমার্ক করুন। লগইন পাতায় অন্য প্যানেলের লিংক শুধু তথ্যের জন্য। মালিকের পাসওয়ার্ড কখনো স্টাফ (Manage) প্যানেলে ব্যবহার করবেন না।',
    'getting_started_s9' => 'লগইন না হলে প্যানেলের ঠিকানা, লগইন তথ্য, অ্যাকাউন্ট চালু নাকি স্থগিত, এবং স্টাফ অনুমতি যুক্ত করা লাগবে কিনা দেখুন।',
